UPDATE public.funnel_steps SET subject='🎉 Bem-vindo(a) à Capimobi, {{nome}}!', content_html='<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f4f6fb;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Arial,sans-serif;color:#0f172a"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f6fb;padding:24px 12px"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 20px rgba(15,23,42,.06)"><tr><td style="background:linear-gradient(135deg,#0ea5e9,#6366f1);padding:24px 28px;color:#ffffff"><table role="presentation" width="100%"><tr><td><div style="font-size:22px;font-weight:800;letter-spacing:-.5px">Cap<span style="color:#fff">i</span><span style="color:#fbbf24">mobi</span></div></td><td align="right"><span style="display:inline-block;background:rgba(255,255,255,.18);padding:6px 12px;border-radius:999px;font-size:11px;font-weight:600;letter-spacing:.3px">DIA 0 · BOAS-VINDAS</span></td></tr></table></td></tr><tr><td style="padding:28px 28px 8px"><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#0f172a;font-weight:700">Olá, {{nome}}! Sua conta tá no ar 👋</h1><p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155">Que bom ter você na <strong>Capimobi</strong>! Você já pode usar <strong>todos os bots de IA</strong> e ferramentas da plataforma:</p><ul style="margin:0 0 16px;padding:0 0 0 4px;list-style:none"><li style="margin:0 0 8px;font-size:14px;line-height:1.5;color:#334155;padding:8px 12px;background:#f8fafc;border-radius:8px;border-left:3px solid #0ea5e9">💰 <strong>Avaliador IA</strong> — preço justo em segundos</li><li style="margin:0 0 8px;font-size:14px;line-height:1.5;color:#334155;padding:8px 12px;background:#f8fafc;border-radius:8px;border-left:3px solid #0ea5e9">✍️ <strong>Copywriter IA</strong> — descrições prontas com emojis</li><li style="margin:0 0 8px;font-size:14px;line-height:1.5;color:#334155;padding:8px 12px;background:#f8fafc;border-radius:8px;border-left:3px solid #0ea5e9">📸 <strong>Analisador de Fotos IA</strong> — feedback profissional</li><li style="margin:0 0 8px;font-size:14px;line-height:1.5;color:#334155;padding:8px 12px;background:#f8fafc;border-radius:8px;border-left:3px solid #0ea5e9">🤖 <strong>Bot de Captação</strong> — leads no automático</li></ul><div style="margin:0 0 16px;padding:12px 14px;background:#eff6ff;border-radius:8px;border-left:3px solid #6366f1;font-size:14px;line-height:1.5;color:#1e293b"><strong>Plus:</strong> sua loja virtual já está no ar com URL personalizada, CRM kanban, contratos, calculadora de ROI e push notifications — <strong>tudo incluso até no plano Grátis</strong>. ✨</div><table role="presentation" width="100%" style="margin:24px 0 8px"><tr><td align="center"><a href="https://capimobi.com.br/painel" style="background:linear-gradient(135deg,#0ea5e9,#6366f1);color:#ffffff;padding:13px 30px;border-radius:10px;text-decoration:none;font-weight:700;font-size:15px;display:inline-block;box-shadow:0 4px 12px rgba(99,102,241,.3)">Acessar meu painel →</a></td></tr></table><p style="margin:18px 0 0;font-size:13px;color:#64748b;line-height:1.5">Nos próximos dias mando dicas curtas pra você bombar de verdade. 😉<br>Abraço,<br><strong style="color:#0f172a">Equipe Capimobi</strong></p></td></tr><tr><td style="background:#f8fafc;padding:14px 28px;text-align:center;font-size:11px;color:#94a3b8;border-top:1px solid #e2e8f0">© Capimobi · Plataforma profissional para corretores de imóveis</td></tr></table></td></tr></table></body></html>' WHERE day_offset=0;
UPDATE public.funnel_steps SET subject='📸 {{nome}}, fotos que vendem (dica do dia 1)', content_html='<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f4f6fb;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Arial,sans-serif;color:#0f172a"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f6fb;padding:24px 12px"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 20px rgba(15,23,42,.06)"><tr><td style="background:linear-gradient(135deg,#0ea5e9,#6366f1);padding:24px 28px;color:#ffffff"><table role="presentation" width="100%"><tr><td><div style="font-size:22px;font-weight:800;letter-spacing:-.5px">Cap<span style="color:#fff">i</span><span style="color:#fbbf24">mobi</span></div></td><td align="right"><span style="display:inline-block;background:rgba(255,255,255,.18);padding:6px 12px;border-radius:999px;font-size:11px;font-weight:600;letter-spacing:.3px">DIA 1 · FOTOS QUE VENDEM</span></td></tr></table></td></tr><tr><td style="padding:28px 28px 8px"><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#0f172a;font-weight:700">{{nome}}, foto ruim espanta cliente 📸</h1><p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155">A primeira foto vale por 80% da decisão. Olha 4 truques que fazem diferença <strong>imediata</strong>:</p><ul style="margin:0 0 16px;padding:0 0 0 4px;list-style:none"><li style="margin:0 0 8px;font-size:14px;line-height:1.5;color:#334155;padding:8px 12px;background:#f8fafc;border-radius:8px;border-left:3px solid #0ea5e9">🌅 <strong>Luz natural</strong> — fotografe entre 9h-11h ou 15h-17h</li><li style="margin:0 0 8px;font-size:14px;line-height:1.5;color:#334155;padding:8px 12px;background:#f8fafc;border-radius:8px;border-left:3px solid #0ea5e9">📐 <strong>Horizontal</strong> sempre — celular deitado, nunca em pé</li><li style="margin:0 0 8px;font-size:14px;line-height:1.5;color:#334155;padding:8px 12px;background:#f8fafc;border-radius:8px;border-left:3px solid #0ea5e9">🛋️ <strong>Ambiente arrumado</strong> — cama feita, bancada limpa</li><li style="margin:0 0 8px;font-size:14px;line-height:1.5;color:#334155;padding:8px 12px;background:#f8fafc;border-radius:8px;border-left:3px solid #0ea5e9">🤖 Use o <strong>Analisador de Fotos IA</strong> antes de publicar</li></ul><div style="margin:0 0 16px;padding:12px 14px;background:#eff6ff;border-radius:8px;border-left:3px solid #6366f1;font-size:14px;line-height:1.5;color:#1e293b">Imóveis com fotos profissionais vendem <strong>32% mais rápido</strong>. Faça o teste hoje.</div><table role="presentation" width="100%" style="margin:24px 0 8px"><tr><td align="center"><a href="https://capimobi.com.br/painel" style="background:linear-gradient(135deg,#0ea5e9,#6366f1);color:#ffffff;padding:13px 30px;border-radius:10px;text-decoration:none;font-weight:700;font-size:15px;display:inline-block;box-shadow:0 4px 12px rgba(99,102,241,.3)">Analisar minhas fotos →</a></td></tr></table><p style="margin:18px 0 0;font-size:13px;color:#64748b;line-height:1.5">Amanhã: como deixar sua loja com a sua cara.<br>Abraço,<br><strong style="color:#0f172a">Equipe Capimobi</strong></p></td></tr><tr><td style="background:#f8fafc;padding:14px 28px;text-align:center;font-size:11px;color:#94a3b8;border-top:1px solid #e2e8f0">© Capimobi · Plataforma profissional para corretores de imóveis</td></tr></table></td></tr></table></body></html>' WHERE day_offset=1;
